import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {BOSS_CATALOG,bossDefinition} from '../src/catalog/bosses.js';
import {blindRequirement,implementedBossEffects} from '../src/catalog/blinds.js';
import {parseState} from '../src/state/validation.js';
import {scoreHand} from '../src/rules/scoring.js';
import {known,success} from './helpers.js';

// Independent fixed oracles transcribed from pinned game.lua P_BLINDS,
// get_blind_amount and get_new_boss; not generated by the catalog or calculator.
// This checks inspected source, never a direct observed Balatro session.
const rows=[
 ['the_hook',1,2,5,600],['the_ox',6,2,5,40000],['the_house',2,2,5,1600],
 ['the_wall',2,4,5,3200],['the_wheel',2,2,5,1600],['the_arm',2,2,5,1600],
 ['the_club',1,2,5,600],['the_fish',2,2,5,1600],['the_psychic',1,2,5,600],
 ['the_goad',1,2,5,600],['the_water',2,2,5,1600],['the_window',1,2,5,600],
 ['the_manacle',1,2,5,600],['the_eye',3,2,5,4000],['the_mouth',2,2,5,1600],
 ['the_plant',4,2,5,10000],['the_serpent',5,2,5,22000],['the_pillar',1,2,5,600],
 ['the_needle',2,1,5,800],['the_head',1,2,5,600],['the_tooth',3,2,5,4000],
 ['the_flint',2,2,5,1600],['the_mark',2,2,5,1600],
 ['amber_acorn',8,2,8,100000],['verdant_leaf',8,2,8,100000],
 ['violet_vessel',8,6,8,300000],['crimson_heart',8,2,8,100000],['cerulean_bell',8,2,8,100000]
] as const;

test('28 boss identities, multipliers, base rewards and earliest White-ante targets match fixed source oracles',()=>{
 assert.equal(BOSS_CATALOG.length,28);assert.equal(new Set(BOSS_CATALOG.map(b=>b.id)).size,28);
 assert.deepEqual(BOSS_CATALOG.map(b=>b.id).sort(),rows.map(r=>r[0]).sort());
 for(const [id,ante,multiplier,reward,target] of rows){
  const b=bossDefinition(id);assert.ok(b,id);assert.equal(b.minAnte,ante,id);assert.equal(b.multiplier,multiplier,id);assert.equal(b.reward,reward,id);assert.equal(b.showdown,ante===8,id);
  assert.ok(b.name.trim()&&b.nameEn.trim()&&b.description.trim()&&b.shortDescription.trim(),id);
  assert.match(b.artId,/^bl_/);assert.doesNotMatch(b.description,/#\d+#|\{[^}]*\}/);
  const calculation=blindRequirement(ante,'boss',id,'blue');assert.ok(calculation.ok,id);assert.equal(calculation.target,target,id);assert.equal(calculation.reward,reward,id);
 }
 assert.equal(bossDefinition('invented_boss'),undefined);
});

test('White ante growth changes targets but not ordinary base reward; five final bosses pay8, not5',()=>{
 const before=structuredClone(BOSS_CATALOG);
 for(const [ante,target] of [[1,600],[2,1600],[3,4000],[4,10000],[5,22000],[6,40000],[7,70000]] as const){
  const result=blindRequirement(ante,'boss','the_window','red');assert.ok(result.ok);assert.equal(result.target,target);assert.equal(result.reward,5);
 }
 for(const id of ['amber_acorn','verdant_leaf','crimson_heart','cerulean_bell'] as const){
  const result=blindRequirement(8,'boss',id,'red');assert.ok(result.ok);assert.equal(result.target,100000);assert.equal(result.reward,8);
 }
 const violet=blindRequirement(8,'boss','violet_vessel','red');assert.ok(violet.ok);assert.equal(violet.target,300000);assert.equal(violet.reward,8);
 assert.deepEqual(BOSS_CATALOG,before,'Queries do not mutate catalog metadata');
});

test('boss pool availability is separate from raw source min10/max10 and never enables endless or other stakes',()=>{
 for(const [id,minAnte] of rows){
  for(let ante=1;ante<=8;ante++)assert.equal(blindRequirement(ante,'boss',id,'blue').ok,minAnte===8?ante===8:ante>=minAnte&&ante<8,`${id}, ante${ante}`);
  assert.equal(blindRequirement(9,'boss',id,'blue').ok,false);assert.equal(blindRequirement(0,'boss',id,'blue').ok,false);
 }
 for(const ante of [NaN,Infinity,1.5])assert.equal(blindRequirement(ante,'boss','the_window','blue').ok,false);
 assert.equal(blindRequirement(1,'boss','the_window','ghost').ok,false);
});

test('numeric metadata for an unimplemented boss never silently enables exact scoring, even when disabled',()=>{
 assert.deepEqual(BOSS_CATALOG.filter(b=>implementedBossEffects(b.id)).map(b=>b.id).sort(),['the_psychic','the_water','the_wall','violet_vessel'].sort());
 for(const disabled of [false,true]){
  const state=success(parseState(readFileSync('examples/shop-purchase.json','utf8')));
  state.observed.nextBlind=known({ante:1,kind:'boss',bossId:known('the_window'),target:known(600),reward:known(5)});
  state.observed.jokerContext=known({bossDisabled:known(disabled)});
  const before=structuredClone(state),metadata=blindRequirement(1,'boss','the_window','blue');assert.ok(metadata.ok);assert.equal(metadata.target,600);assert.equal(metadata.reward,5);
  const scored=scoreHand(state,{cardIds:['8S','8H'],discardsRemaining:3});assert.equal(scored.ok,false);
  if(!scored.ok)assert.ok(scored.errors.some(e=>e.code==='unsupported_blind'),JSON.stringify(scored));
  assert.deepEqual(state,before);
 }
});
